// ==========================================================================
// DATA ANALYST CONTEXT & INTENT PARSER
// ==========================================================================
const body = $input.first()?.json?.body || $input.first()?.json || {};

const komoditas = body.komoditas || body.commodity || 'Cabai Merah Keriting';
const lokasi = body.lokasi || body.location || 'Lembang, Jawa Barat';
const luas_ha = parseFloat(body.luas_ha || body.area_ha || 1.5);
const chart_format = (body.chart_format || body.format || 'echarts').toLowerCase();
const predicted_yield = parseFloat(body.predicted_yield || body.yield_ton_ha || 14.5);

// Harmonize sub-domain inputs from other workflows or client payload
const soil_data = body.soil_data || body.soil || {
  nitrogen: body.n || body.nitrogen || 95,
  phosphorus: body.p || body.phosphorus || 48,
  potassium: body.k || body.potassium || 58,
  ph: body.ph || 6.4,
  moisture: body.moisture || 70
};

const market_data = body.market_data || body.market || {
  current_price: body.current_price || body.harga_jual_rp_kg || 36000,
  target_price: body.target_price || 39500,
  historical_prices: body.historical_prices || [31000, 32500, 31800, 33500, 35000, 36000]
};

const weather_data = body.weather_data || body.weather || {
  rainfall_mm: body.rainfall_mm || body.curah_hujan || 175,
  temperature_c: body.temperature_c || body.suhu || 24.2
};

const financial_data = body.financial_data || body.financials || {
  total_biaya_rp: body.total_biaya_rp || (45000000 * luas_ha)
};

return [{
  json: {
    komoditas: komoditas,
    lokasi: lokasi,
    luas_ha: luas_ha,
    predicted_yield: predicted_yield,
    chart_format: chart_format,
    soil_data: soil_data,
    market_data: market_data,
    weather_data: weather_data,
    financial_data: financial_data,
    urea_kg: body.urea_kg || (200 * luas_ha),
    npk_kg: body.npk_kg || (300 * luas_ha),
    organik_kg: body.organik_kg || (2000 * luas_ha),
    request_id: `analyst_${Date.now()}`,
    timestamp: new Date().toISOString()
  }
}];

// ==========================================================================
// MODERN VISUALIZATION HUB & DASHBOARD COMPOSER
// ==========================================================================
const res = $input.first().json;
const parserData = $('Context & Intent Parser').item.json;
const data = res.data || {};

const visualizations = data.visualizations || {};
const overallScore = data.overall_health_score || 80;

// Determine Status Tier Badge
let statusBadge = '🟢 PRIMA & MENGUNTUNGKAN';
if (overallScore < 60) {
  statusBadge = '🔴 PERLU MITIGASI RISIKO SEGERA';
} else if (overallScore < 75) {
  statusBadge = '🟡 CUKUP SEHAT DENGAN CATATAN';
}

return [{
  json: {
    success: res.success !== false,
    request_id: parserData.request_id,
    title: `Laporan Analis Data Eksekutif: ${data.komoditas || parserData.komoditas} (${data.lokasi || parserData.lokasi})`,
    overall_score: overallScore,
    status_badge: statusBadge,
    executive_summary: data.executive_summary,
    key_findings: data.key_findings || [],
    strategic_action_plan: data.strategic_action_plan || [],
    pillar_scorecard: {
      agronomic_health: data.agronomic_health_score,
      market_opportunity: data.market_health_score,
      financial_resilience: data.financial_resilience_score,
      climate_risk_index: data.climate_risk_score,
      esg_carbon_rating: data.esg_carbon_score
    },
    financial_diagnostics: data.financial_metrics,
    market_diagnostics: data.market_dynamics,
    risk_assessment: data.risk_assessment,
    carbon_diagnostics: data.carbon_diagnostics,
    visualizations: visualizations,
    timestamp: new Date().toISOString()
  }
}];
